{
  "name": "insurancePolicyIds",
  "in": "query",
  "required": true,
  "description": "A common-separated list of insurance policy identifiers. Used to retrieve all insurance policies authorized by the User, which matches the `insurancePolicyIds` data for a given Consent at Consent Manager.\n\nThis parameter is **mandatory**. However, where `o3-is-caap-consent-operation` is `true` an empty value will be sent, as insurance policy selection has not been completed at CAAP.\n\nLFIs using CAAP **MUST** follow the guidance in `o3-is-caap-consent-operation` parameter.",
  "schema": {
    "type": "string"
  },
  "explode": false
}

{
  "name": "o3-is-caap-consent-operation",
  "in": "header",
  "required": false,
  "description": "Flag to indicate that query originates from CAAP and is invoked to get available insurance policies to allow the User to authorize access to one-or-more insurance policies.\n\nLFIs must return all eligible policies when value is `true` to facilitate User selection of policies in the CAAP application.",
  "schema": {
    "type": "boolean"
  }
}

